  // **堆变厚**。它跟【削水】【退潮】是同一条轴的反方向
  //（那两件往下压造 0 点，这一件往上顶造「出界点数」）。
  //
  // ---- 它打的是这一季反复撞到的那堵墙 ----
  //
  // 「堆常年 2.1 张厚」卡死过：21 匹配的预算轴（天花板 +0.55）、锚点轴
  //（+0.16）、齐顶的落点（`pair raise peak` 协同 −0.08），而 16.9 那张表
  // 写明顺子族 / 归深 / 吃水 / 一色**吃的是同一个约束**。
  // **推牌是唯一撬动过它的机制（+2.55），代价是超档 1.46。**
  // 这一件换一条路加厚：不从牌库搬牌，**只让已经在堆上的牌钓不走**。
  //
  // ---- 两条事前就该亮的红旗 ----
  //
  // **一、这是压底族的形状**（检查表最后一条：「压底 / 铺场 / 让堆变厚
  //   变死的，先回来读『压底族六件』」—— 那六件 X 全负，死因「兑现牌遇不上」）。
  //   用户的说法「**等待收割件**」正是承认了这一点，所以它的立项读数
  //   **只能是 `pair`，不是单件 X**（照【涌泉】那条：pair 不出协同就不要做）。
  //
  //   ⚠ **但 16.9 给压底族留了一个口子，而这一件正好在口子里**：
  //  「压底族**抹点数**，而顺子 / 归深 / 吃水全靠点数 —— 它们互斥。
  //   那七种被证伪的配对里**根本没有『保留点数地铺牌 + 点数线兑现』这一种。**」
  //   这一件**保留点数**（+N 不是抹），所以它不在那七种里。
  //
  // **二、「抬过 13」和「抹点数」在「谁也钓不走」上等价** ——
  //   区别只在**还有谁够得着**，而这张表就是它的配件清单：
  //     ✓【齐顶】抄同色最大 → 抬得越高它越准，**而且它钓的就是那张**
  //     ✓【磁钩】差 1（够得着 14，手里要有 K）
  //     ✓【顺子】14-15-16 照样连 —— 要三张都抬过去
  //     ✓【收色】【顺色】按花色；【撒网】按奇偶
