  //
  // ---- 它解的是这一族唯一的死结 ----
  //
  // 【大数】的障碍是「匹配不到」，而那件事**没有豁免口**
  //（结冰的障碍是「收不走」，而收牌有 takeAt 那个单一入口可以开豁免）。
