  // ---------- 【唤潮】（原型，2026-10-20 · 用户定）----------
  //
  // **「场上存在比 13 大的点数 → 此牌变成点数最大的那个数；
  //    否则使双方 N 张手牌带上【涨潮：全场点数 +M】。」**
  //
  // ---- 它一次绕开了这一季踩过的三个坑 ----
  //
  // **一、两支互斥 = 自己造料自己收**（文档给两件式困局的第一条出路：
